def fitpoly(eps_exp, tdeg, cdeg):
    cols=[T**k for k in range(tdeg+1)]
    cols+= [eps**eps_exp*T**k for k in range(cdeg+1)]
    X=np.column_stack(cols)
    c,*_=np.linalg.lstsq(X,sigma,rcond=None)
    res=sigma-X@c
    return np.sqrt(np.mean(res**2)), c
